// PS/2 mouse message boundary finder
module TopModule(
  input  clk,
  input  reset,
  input  [7:0] in,
  output reg done
);
  reg [2:0] state;
  reg [7:0] buf [0:2];
  reg [2:0] byte;
  reg [2:0] bitpos;
  reg [2:0] parity;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      done <= 0;
      byte <= 0;
      bitpos <= 0;
      parity <= 0;
    end else begin
      case (state)
        0: begin // wait for start bit
          if (in[0]) state <= 1;
        end
        1: begin // get byte 1
          buf[0] <= in;
          byte <= 0;
          bitpos <= 0;
          parity <= ~in[3];
          state <= 2;
        end
        2: begin // get byte 2
          buf[1] <= in;
          byte <= 1;
          bitpos <= 0;
          parity <= parity + ~in[3];
          state <= 3;
        end
        3: begin // get byte 3
          buf[2] <= in;
          byte <= 2;
          bitpos <= 0;
          parity <= parity + ~in[3];
          if (parity != 0) state <= 0; // parity error, start over
          else if (in[3] == 0) state <= 0; // not the end of a message, start over
          else begin // message complete
            // check that the bytes are in order and that the message
            // has the correct start and end bits
            if ((buf[0] != 8'hFA) || (buf[1] != (8'hFE | (byte[7] << 6))) || (buf[2] != (byte[6:0] ^ 8'hFF))) state <= 0;
            else done <= 1;
            state <= 0;
          end
        end
      endcase
      if (state != 0) bitpos <= bitpos + 1;
    end
  end
endmodule

