// two bytes may be 1 or 0 depending on data).
//
// This module implements a finite state machine that will search for
// message boundaries when given an input byte stream. The algorithm
// we'll use is to discard bytes until we see one with in[3]=1. We then
// assume that this is byte 1 of a message, and signal the receipt of a
// message once all 3 bytes have been received (done). The FSM signals
// done in the cycle immediately after the third byte of each message was
// successfully received.
module TopModule (
  input  clk,
  input  reset,
  input  [7:0] in,
  output reg done
);
  reg [1:0] state;
  reg [7:0] bytes [0:2];
  reg [2:0] byte_idx;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'd0;
      done <= 1'b0;
      byte_idx <= 3'd0;
    end else begin
      case (state)
        2'd0: begin // Wait for first byte with in[3]=1
          if (in[3]) begin
            bytes[0] <= in;
            state <= 2'd1;
            byte_idx <= 3'd1;
          end
        end
        2'd1: begin // Wait for second byte
          bytes[1] <= in;
          state <= 2'd2;
          byte_idx <= 3'd2;
        end
        2'd2: begin // Wait for third byte
          bytes[2] <= in;
          state <= 2'd0;
          byte_idx <= 3'd0;
          done <= 1'b1;
        end
      endcase
    end
  end
endmodule

